begin;
create function pg_temp.assert_cohort(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',message;end if;end$$;
insert into auth.users(id,email,raw_app_meta_data) values
 ('22222222-2222-4222-8222-222222222222','identity-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa@members.valuelog.invalid','{"identity_issuer":"word-wallet-web","identity_did":"did:iov:member:aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}'),
 ('33333333-3333-4333-8333-333333333333','identity-bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb@members.valuelog.invalid','{"identity_issuer":"word-wallet-web","identity_did":"did:iov:member:bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"}');
select public.admit_value_log_member('22222222-2222-4222-8222-222222222222','did:iov:member:aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','identity-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa@members.valuelog.invalid');
select public.admit_value_log_member('33333333-3333-4333-8333-333333333333','did:iov:member:bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','identity-bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb@members.valuelog.invalid');
select public.setup_value_log_member('22222222-2222-4222-8222-222222222222','Synthetic A','Asia/Kolkata');
select public.setup_value_log_member('33333333-3333-4333-8333-333333333333','Synthetic B','Europe/London');
do $$declare actor uuid:='11111111-1111-4111-8111-111111111111';a uuid:='22222222-2222-4222-8222-222222222222';b uuid:='33333333-3333-4333-8333-333333333333';d uuid:=gen_random_uuid();d2 uuid:=gen_random_uuid();r uuid:=gen_random_uuid();r2 uuid:=gen_random_uuid();occ uuid:=gen_random_uuid();lease uuid;claim jsonb;cipher jsonb:='{"ciphertext":"syntheticencryptedtext","iv":"iiiiiiiiiiiiiiii","authTag":"tttttttttttttttttttttttt","keyVersion":1,"digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}';receipt jsonb:='{"kind":"cohort_review_pending"}';u uuid;did text;alias text;h text;
begin
 perform cohort_command(actor,'invite',jsonb_build_object('id',gen_random_uuid(),'hash',repeat('c',64),'communities',jsonb_build_array('gfe')));
 perform cohort_command(a,'enroll',jsonb_build_object('hash',repeat('c',64),'house','house_of_sis','communities',jsonb_build_array('gfe'),'consent',true,'startingValuesConfirmed',true));
 begin perform cohort_command(b,'enroll',jsonb_build_object('hash',repeat('c',64),'house','house_of_bros','communities','[]'::jsonb,'consent',true,'startingValuesConfirmed',true));raise exception 'FAIL: one-use invite stolen';exception when raise_exception then if sqlerrm<>'INVITATION_UNAVAILABLE' then raise;end if;end;
 perform cohort_command(actor,'invite',jsonb_build_object('id',gen_random_uuid(),'hash',repeat('d',64),'communities','[]'::jsonb));
 update cohort_invitations set expires_at=now()-interval '1 second' where token_hash=repeat('d',64);
 begin perform cohort_command(b,'enroll',jsonb_build_object('hash',repeat('d',64),'house','house_of_bros','communities','[]'::jsonb,'consent',true,'startingValuesConfirmed',true));raise exception 'FAIL: expired invite used';exception when raise_exception then if sqlerrm<>'INVITATION_UNAVAILABLE' then raise;end if;end;
 perform cohort_command(actor,'invite',jsonb_build_object('id',gen_random_uuid(),'hash',repeat('e',64),'communities','[]'::jsonb));
 perform cohort_command(actor,'revoke_invite',jsonb_build_object('id',(select id from cohort_invitations where token_hash=repeat('e',64))));
 begin perform cohort_command(b,'enroll',jsonb_build_object('hash',repeat('e',64),'house','house_of_bros','communities','[]'::jsonb,'consent',true,'startingValuesConfirmed',true));raise exception 'FAIL: revoked invite used';exception when raise_exception then if sqlerrm<>'INVITATION_UNAVAILABLE' then raise;end if;end;
 perform cohort_command(actor,'invite',jsonb_build_object('id',gen_random_uuid(),'hash',repeat('f',64),'communities','[]'::jsonb));
 perform cohort_command(b,'enroll',jsonb_build_object('hash',repeat('f',64),'house','house_of_bros','communities','[]'::jsonb,'consent',true,'startingValuesConfirmed',true));
 update cohort_enrollments set boundary_at=now()-interval '6 hours' where owner_id=a;
 perform save_native_log_draft(a,d,0,cipher);
 perform confirm_cohort_log(a,d,1,repeat('a',64),'Approved',jsonb_build_array(jsonb_build_object('id',r,'occurrenceId',occ,'start',now()-interval '4 hours','end',now()-interval '3 hours','content',cipher)),receipt);
 perform save_native_log_draft(a,d2,0,cipher);
 begin perform confirm_cohort_log(a,d2,1,repeat('a',64),'Approved',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'occurrenceId',gen_random_uuid(),'start',now()-interval '2 hours','end',now()-interval '1 hour','content',cipher),jsonb_build_object('id',gen_random_uuid(),'occurrenceId',gen_random_uuid(),'start',now()-interval '4 hours','end',now()-interval '3 hours','content',cipher)),receipt);raise exception 'FAIL: overlap committed';exception when raise_exception then if sqlerrm<>'NATIVE_TIMELINE_OVERLAP' then raise;end if;end;
 perform pg_temp.assert_cohort((select count(*)=1 from cohort_records),'batch rollback retains no partial entries');
 perform pg_temp.assert_cohort((select status='draft' from native_log_drafts where id=d2),'failed batch keeps recoverable draft');
 begin perform confirm_cohort_log(b,d2,1,repeat('a',64),'Approved','[]',receipt,r);raise exception 'FAIL: another owner corrected A';exception when raise_exception then if sqlerrm<>'UNAUTHORIZED' then raise;end if;end;
 perform confirm_cohort_log(a,d2,1,repeat('a',64),'Approved correction',jsonb_build_array(jsonb_build_object('id',r2,'occurrenceId',occ,'start',now()-interval '4 hours','end',now()-interval '3 hours','content',cipher)),receipt,r);
 perform confirm_cohort_log(a,d2,1,repeat('a',64),'Approved correction','[]',receipt,r);
 perform pg_temp.assert_cohort((select count(*)=2 from cohort_records),'correction and retry keep original and one revision');
 perform pg_temp.assert_cohort((select review_status='superseded' from cohort_records where id=r),'original not deleted');
 perform pg_temp.assert_cohort((select revision=2 and supersedes=r and occurrence_id=occ from cohort_records where id=r2),'correction preserves occurrence identity');
 perform cohort_command(actor,'assign_operator','{"did":"did:iov:member:bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"}');
 begin perform cohort_command(a,'accept_operator','{"consent":true}');raise exception 'FAIL: wrong operator accepted';exception when raise_exception then if sqlerrm<>'UNAUTHORIZED' then raise;end if;end;
 perform cohort_command(b,'accept_operator','{"consent":true}');lease:=gen_random_uuid();claim:=claim_cohort_review(a,r2,lease);
 perform cohort_command(actor,'revoke_membership',jsonb_build_object('owner',a,'community','gfe'));
 perform pg_temp.assert_cohort(not finish_cohort_review(a,r2,lease,(claim->'delegation'->>'id')::uuid,repeat('a',64),gen_random_uuid(),'reviewed',cipher),'membership withdrawal invalidates in-flight decision');
 update cohort_records set lease_until=now()-interval '1 second' where id=r2;lease:=gen_random_uuid();claim:=claim_cohort_review(a,r2,lease);
 perform cohort_command(b,'agent_pause','{"active":false}');
 perform cohort_command(b,'agent_pause','{"active":true}');
 perform pg_temp.assert_cohort(not finish_cohort_review(a,r2,lease,(claim->'delegation'->>'id')::uuid,repeat('a',64),gen_random_uuid(),'reviewed',cipher),'operator pause invalidates old lease even after resume');
 perform cohort_command(a,'leave_membership','{"community":"house_of_sis"}');
 begin perform cohort_command(a,'consent','{"consent":true}');raise exception 'FAIL: resumed revoked house without invite';exception when raise_exception then if sqlerrm<>'MEMBERSHIP_REQUIRED' then raise;end if;end;
 perform cohort_command(actor,'invite',jsonb_build_object('id',gen_random_uuid(),'hash',repeat('9',64),'communities',jsonb_build_array('house_of_sis')));
 perform cohort_command(a,'accept_memberships',jsonb_build_object('hash',repeat('9',64),'communities',jsonb_build_array('house_of_sis'),'consent',true));
 perform pg_temp.assert_cohort((select active and review_consent from cohort_enrollments where owner_id=a),'new accepted invitation can resume without resetting baseline');
 for n in 1..9 loop
  u:=gen_random_uuid();did:='did:iov:member:'||gen_random_uuid()::text;alias:='identity-'||encode(digest(u::text,'sha256'),'hex')||'@members.valuelog.invalid';h:=encode(digest(did,'sha256'),'hex');
  insert into auth.users(id,email,raw_app_meta_data) values(u,alias,jsonb_build_object('identity_issuer','word-wallet-web','identity_did',did));
  perform admit_value_log_member(u,did,alias);perform setup_value_log_member(u,'Synthetic capacity member','UTC');
  perform cohort_command(actor,'invite',jsonb_build_object('id',gen_random_uuid(),'hash',h,'communities','[]'::jsonb));
  if n<=8 then perform cohort_command(u,'enroll',jsonb_build_object('hash',h,'house','house_of_bros','communities','[]'::jsonb,'consent',true,'startingValuesConfirmed',true));
  else begin perform cohort_command(u,'enroll',jsonb_build_object('hash',h,'house','house_of_bros','communities','[]'::jsonb,'consent',true,'startingValuesConfirmed',true));raise exception 'FAIL: eleventh enrolled';exception when raise_exception then if sqlerrm<>'COHORT_FULL' then raise;end if;end;end if;
 end loop;
 perform pg_temp.assert_cohort((select count(*)=10 from cohort_enrollments),'exact ten-person bound');
end$$;
select 'PASS: cohort capacity, corrections, rollback, expired/revoked invitations and operator/membership revocation' as result;
rollback;
